# Search for available Hanes ComfortSoft Short Sleeve T-Shirt variants by preferred color, ensuring inventory >= 2

access_token = apis.amazon.login(username='kevin.blac@gmail.com', password=apis.supervisor.show_account_passwords()[0]['password'])['access_token']

base_query = "Hanes Men's ComfortSoft Short Sleeve T-Shirt"
colors_preference = ['red', 'black', 'navy blue']
relative_size = 'extra-large'

api = apis.amazon.search_products

results_by_color = {}

for color in colors_preference:
    color_candidates = []
    page_index = 0
    while True:
        page = api(query=base_query, color=color, relative_size=relative_size, page_index=page_index, page_limit=20)
        if not page:
            break
        # filter exact product name
        for r in page:
            if r.get('name') == base_query and r.get('relative_size') == relative_size and r.get('color') == color:
                color_candidates.append(r)
        page_index += 1
    results_by_color[color] = color_candidates
    print('color', color, 'candidates', len(color_candidates), 'with inventory>=2', sum(1 for r in color_candidates if r.get('inventory_quantity', 0) >= 2))

# pick first preferred color with any candidate
for color in colors_preference:
    cand = [r for r in results_by_color[color] if r.get('inventory_quantity', 0) >= 2]
    if cand:
        # choose highest rating then lowest price
        cand_sorted = sorted(cand, key=lambda x: (-x.get('rating', 0), x.get('price', 0)))
        choice = cand_sorted[0]
        print('chosen_color', color)
        print('chosen_product_id', choice['product_id'], 'inventory', choice['inventory_quantity'], 'price', choice['price'], 'rating', choice['rating'])
        break
else:
    print('No color has inventory_quantity >=2. Available candidates (min inventory) by color:')
    for color in colors_preference:
        cand = results_by_color[color]
        if cand:
            best = sorted(cand, key=lambda x: (-x.get('rating',0), x.get('price',0)))[0]
            print(color, 'best product_id', best['product_id'], 'inventory', best['inventory_quantity'])
        else:
            print(color, 'no candidates')

